from h34 import *
M=mcq;F=tf;S=short
steps=["1 Wet the clay","2 Pound and knead","3 Shape on the wheel","4 Dry the pot","5 Bake in the kiln","6 Make patterns"]
b=''
for i,s in enumerate(steps):
    x=10+i*95
    b+=f'<rect x="{x}" y="60" width="85" height="90" rx="10" fill="#ffe9cc" stroke="#8d5524" stroke-width="2"/><text x="{x+42}" y="100" text-anchor="middle" font-size="12" font-weight="bold">{s.split(" ",1)[0]}</text><text x="{x+42}" y="120" text-anchor="middle" font-size="11">{s.split(" ",1)[1]}</text>'
    if i<5: b+=f'<path d="M{x+86} 105 L{x+94} 105" stroke="#333" stroke-width="3"/>'
b+='<text x="290" y="30" text-anchor="middle" font-size="18" font-weight="bold">How a pot is made</text><text x="290" y="190" text-anchor="middle" font-size="14">Clay + water, a spinning stone wheel, a hot kiln, and patterns to finish</text>'
svgfile('c3-pot-steps.svg',580,215,b)
chapter(3,'evs','making-things','Making Things',
 ("Who made your pot?","We use a water pot, a gullak, a bird bath and a kulhad cup. What are they made of, and who makes them and how? Today we follow a potter's family and a boy who loves to watch walls grow."),
 [("A potter's family",["In a town by the sea, Mini watched her Appooppan, her grandfather, make a pot.","He took clay and made it wet, adding enough water to get the right thickness.","He pounded the clay well and kneaded it like dough, so that it was neither too watery nor too dry.","Then he put the clay on a stone wheel and shaped it by spinning the wheel.","When the pots had dried, Ammu moved them into a very hot oven called a kiln, where the fire baked them.","Then the pot was ready for use, and the family made patterns on some pots to make them look more beautiful."]),
  ("Why the kiln, and what else a potter makes",["Baking in the kiln makes the soft clay hard and strong, so the pot does not melt in water.","Potters make water pots, cups like kulhads, piggy banks called gullaks, bird baths and many other things.","Mini was too young to use the wheel, but she helped by making patterns and colouring the pots.","Her favourite clay item was her piggy bank, which she decorated and used to save money.","We can help our parents and grandparents in small ways too."]),
  ("Make your own clay",["With the help of elders we can make our own clay.","We collect soil from a wet or muddy place and remove big pebbles, sand, leaves and plant parts using a net or sieve.","We put the soil in a flat vessel of water, and after a few days we pour away the water on top.","Then we make a dough that we can shape into a ball, and make two things we like and dry them in the sun."]),
  ("Patterns in nature and on pots",["Patterns are found everywhere in nature, like spots on a leopard and stripes on a squirrel.","Neem leaves on a branch make a pattern, and so do the skins of zebras, peacocks, cats, tigers, butterflies and fish.","Artists who paint on pots get ideas from nature, using its shapes and colours.","A pattern has repeating shapes and lines, and we can find patterns on plants, animals and things, and decorate objects with our own patterns.","Pottery from different parts of India has beautiful patterns."]),
  ("Brick by brick",["Bricks are also made of mud, just like the pots Appooppan made.","Bricks are shaped in moulds, like the moulds for idli, cake, dhokla or kulfi, and become hard after baking in a kiln.","Bricks are used to build houses, schools and hospitals.","Rohan lives in Jaipur and loves to watch brick walls grow day by day until they become a big building."]),
  ("Different houses",["Not all houses are made of bricks.","In warm areas people build traditional mud houses with natural materials like grass and wood to keep inside cool.","Instead of cement, many use cow dung to make smooth walls and floors, which keeps the heat out and insects away.","Mud houses are better for the environment because they use natural materials found nearby.","We can look at the houses around us and find out what they are made of."]),
  ("Make a wall and stay safe",["We can make small bricks from a matchbox mould, paper boxes, clay or atta dough and stack them in two ways to see which wall is sturdier.","Rohan's father follows safety rules at work: he wears a helmet with a strap, a safety vest and sturdy shoes.","We also have safety rules at home and at school."])],
 [("Put the steps of pot making in order.",[("Wet the clay and add enough water.","The clay should be neither too watery nor too dry."),("Pound and knead it like dough.","Kneading makes it smooth."),("Shape it on the spinning stone wheel.","The wheel gives the round shape."),("Let it dry, then bake in the kiln.","Baking makes it hard."),("Make patterns to decorate it.","Patterns make it beautiful.")]),
  ("Which is sturdier: bricks stacked in a staggered pattern or in straight columns?",[("Stack small bricks both ways with some clay or atta.","We test both walls."),("Push gently on each wall.","The one that stays up longer is sturdier."),("The staggered wall holds better because each brick sits across the gap below.","Overlapping bricks hold each other.")]),
  ("Why do some people build mud houses in warm areas?",[("Mud, grass and wood are natural materials.","They are easy to find nearby."),("Cow dung on walls and floors keeps heat out.","The house stays cool."),("It also keeps insects away.","So the house is comfortable and good for the environment.")])],
 ("Tell a friend how a pot is made and why a kiln is needed.",["The clay is wetted, pounded and kneaded, then shaped on a wheel","The pot is dried and baked in a kiln so that it becomes hard","Patterns come from ideas in nature","Bricks are also made of mud and baked in a kiln"],["A pot is ready as soon as it is shaped","Bricks are made of metal","All houses are made of bricks"]),
 ["A potter wets, pounds and kneads clay, shapes it on a wheel, dries it and bakes it in a kiln.","A kiln is a very hot oven that makes clay pots and bricks hard.","Patterns have repeating shapes and lines and are found in plants, animals and things.","Bricks are made in moulds from mud and baked, and houses can also be made of mud, grass and wood.","Safety rules, like wearing a helmet at a building site, keep us safe."],
 [M("mt-1",1,"What is a kiln?","A very hot oven where pots and bricks are baked",[("A kind of pot","It is the oven for baking pots."),("A potter's wheel","The wheel shapes the clay."),("A type of brick","It bakes bricks.")],"The potter's oven is called a kiln.",None),
  M("mt-2",1,"What is a pot made from?","Clay",[("Plastic only","Traditional pots are made from clay."),("Paper","Paper would melt in water."),("Glass","Glass is not used for clay pots.")],"Potters make pots from clay.",None),
  F("mt-3",1,"Bricks are made in moulds.",True,"Like idli or kulfi moulds, brick moulds give them shape."),
  M("mt-4",1,"Why is a pot baked in a kiln?","To make it hard and strong",[("To make it wet","Baking dries it."),("To make it soft","Baking makes it hard."),("To make it a toy","The purpose is to make it strong.")],"Baking makes clay hard and strong.",None),
  S("mt-5",2,"Spots on a leopard and stripes on a squirrel are examples of ____ in nature.",["patterns","pattern"],"Repeating shapes and lines make patterns.",[("pots","Pots are made by people.")]),
  M("mt-6",2,"Why do mud houses stay cool?","Natural materials like mud, grass and wood keep the heat out",[("They are painted white","Colour is not the reason in the text."),("They have no roof","They have a roof."),("They are always near the sea","Where they are is not the reason.")],"Mud, grass and wood help keep the house cool.",None),
  M("mt-7",2,"What does cow dung do on mud house walls and floors?","Keeps heat out and stops insects entering",[("Makes them taller","It does not do that."),("Makes them colourful","The text says it keeps heat and insects out."),("Makes them noisy","It has nothing to do with sound.")],"Cow dung makes smooth walls and keeps heat and insects out.",None),
  F("mt-8",2,"We can make our own clay from muddy soil.",True,"We remove stones, mix with water and wait for it to settle."),
  M("mt-9",2,"What does Rohan's father wear for safety at work?","A helmet with a strap, a safety vest and sturdy footwear",[("Sandals only","That is not safe."),("A hat only","A helmet is safer."),("Nothing special","Safety gear is important.")],"Safety gear protects workers on a building site.",None),
  M("mt-10",3,"Which wall is sturdier, and why?","The one where bricks overlap, because each brick supports the ones below",[("The one with straight columns","Straight columns fall more easily."),("Both are the same","They are not the same."),("The one with no bricks","A wall needs bricks.")],"Overlapping bricks hold each other in place.",None),
  S("mt-11",3,"A small box shaped like an idli mould that gives the shape to a brick is a ____.",["mould","moulds"],"A mould gives its shape to clay or batter.",[("kiln","A kiln is an oven.")]),
  M("mt-12",3,"Why do artists copy patterns from nature on pots?","Nature gives them ideas of shapes and colours",[("Nature does not have patterns","It has many."),("Pots cannot have patterns","They can."),("Only machines can make patterns","Artists make them too.")],"Many artists take ideas from patterns in nature.",None)],
 svgs=[("c3-pot-steps","Six steps of making a pot","Wet, knead, shape on the wheel, dry, bake in the kiln and decorate.")])
